  "lokalna_kuhinja": {
    "opis": "Brodsko-posavska kuhinja tipična je slavonska kuhinja s naglaskom na riblju tradiciju uz Savu i klasične slavonske specijalitete.",
    "jela": [
      {
        "naziv": "Fiš-paprikaš",
        "opis": "Kralj brodske kuhinje! Gusti riblji paprikaš od šarana, soma ili štuke, začinjen sa slavonskom crvenom paprikom. Kuha se u kotliću na otvorenoj vatri. Autentičan okus Save u svakom zalogaju."
      },
      {
        "naziv": "Slavonski kulen",
        "opis": "Zaštićena oznaka izvornosti (ZOI). Fermentirana kobasica od svinjskog mesa i slatke/ljute crvene paprike, dimljena i sušena. Slavonski kulen je gastro-ambasador cijele regije."
      },
      {
        "naziv": "Čobanac",
        "opis": "Gusti slavonski gulaš od miješanog mesa (svinjetina, teletina, divljač), začinjen paprikama i lukom. Kuhanje traje satima na laganoj vatri u kotliću."
      },
      {
        "naziv": "Šaran s roštilja",
        "opis": "Svježi savski šaran pripreman na roštilju ili u kotliću. Jednostavno začinjen, izvrstan okus. Brodska delikatesa uz rijeku Savu."
      },
      {
        "naziv": "Kobasice i suhomesnati proizvodi",
        "opis": "Brodska tradicija: domaće kobasice (krvavice, češnjovke), slanina, sušena šunka — sve po tradicionalnim receptima s okusom dima i paprike."
      },
      {
        "naziv": "Slavonska domaća rakija",
        "opis": "Šljivovica i komovica — tradicijska slavonska rakija, pečena kod domaćina. Često se nudi kao dobrodošlica gostima."
      },
      {
        "naziv": "Brodski kolači",
        "opis": "Domaći kolači po receptima brodskih baka: orahnjača, makovnjača, štrukli sa sirom, uštipci — sve umočeno u tradiciju posavske kuhinje."
      }
    ]
  },
